INSERT INTO farm_types (name, display_name, description) VALUES
    ('indoor',     'Indoor',     'Fully controlled environment inside a building — a grow room, warehouse, or vertical rack system where light, temperature, humidity, CO2, and nutrients are all managed artificially. Crops are usually grown soilless (hydroponics or aeroponics) under LED lighting, enabling year-round production regardless of outside weather. Best suited to leafy greens, herbs, and microgreens. Water use is minimal and pests are largely excluded, but energy for lighting and cooling is the main operating cost.'),
    ('outdoor',    'Outdoor',    'Traditional open-field farming where crops grow in natural soil under sunlight and rainfall, following seasonal sowing-to-harvest cycles. Suited to large-scale production of grains, vegetables, fruits, and fodder at the lowest cost per unit area. Success depends heavily on weather, soil health, irrigation, and pest pressure, so planning revolves around seasons, rotations, and machinery schedules rather than environmental controls.'),
    ('greenhouse', 'Greenhouse', 'Protected cultivation inside a glass or poly-covered structure that traps solar warmth while shielding crops from rain, wind, and many pests. Climate is actively managed — ventilation, heating, shading, and humidity control — which extends the growing season and raises yields well above open-field levels on the same footprint. Commonly used for tomatoes, cucumbers, peppers, and flowers, typically with drip irrigation and growing bags or beds. Strikes a balance between the control of indoor farming and the costs of open-field growing.'),
    ('mixed',      'Mixed',      'A farm that runs two or more growing environments side by side — for example open fields plus a greenhouse or an indoor grow room. The combination spreads weather and market risk, keeps supply steady across seasons, and lets high-value sensitive crops stay protected while bulk crops grow outside. Planning involves sequencing production across environments so they complement rather than duplicate each other.')
